insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('ecoDMS', 'ecodms', 'Preiswertes Archivsystem für kleine Unternehmen', 'Günstiges, lokal betriebenes Archiv- und Dokumentenmanagement-System für kleine Unternehmen.', '<p>ecoDMS ist ein preiswertes Archiv- und DMS-System, das lokal oder auf einem eigenen Server betrieben wird. Belege werden gescannt, per OCR durchsuchbar gemacht und revisionssicher abgelegt.</p><p>Die Lizenzierung erfolgt als einmaliger Kauf pro gleichzeitigem Nutzer.</p>', null, (select id from public.categories where slug = 'dokumentenmanagement'), 74.79, 'EUR', 'once', true, 'once', true, null, false, false, '[]'::jsonb, 'einmalige Lizenz, ab 89 € inkl. MwSt.', '["Revisionssichere Archivierung","Volltextsuche & OCR","Versionierung","Rollen & Rechte","E-Mail-Archivierung"]'::jsonb, '["Einmalige Lizenz","Lokale Datenhaltung","Günstig für kleine Betriebe"]'::jsonb, '["Outlook","Microsoft Office","Thunderbird"]'::jsonb, '["Sehr günstig","Daten bleiben im Haus"]'::jsonb, '["Eigener Server nötig","Workflows begrenzt"]'::jsonb, 'Kleine Unternehmen und Selbstständige mit eigener IT.', null, 'ja', 'nein', '[]'::jsonb, null, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.ecodms.de', 'keins', 'ecoDMS GmbH', null, 'Aachen', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 3.8, 4.8, 3.8, 4.1, 'ecoDMS ist das günstigste revisionssichere Archiv in diesem Vergleich, mit einer einmaligen Lizenz ab 89 € inklusive Mehrwertsteuer. Ideal für kleine Betriebe, die ihr Papierarchiv selbst digitalisieren wollen.', '<h3>Das Konzept</h3><p>ecoDMS archiviert Dokumente revisionssicher, erkennt Texte automatisch und legt sie nach Regeln ab. Die Software läuft im eigenen Netz, etwa auf einem kleinen Server oder NAS.</p><h3>Kosten</h3><p>Die Lizenz kostet einmalig ab 89 € inklusive Mehrwertsteuer, ein E-Mail-Archiv 69 €. Das Paket ecoDMS ONE mit Support und Wartung für die Vertragslaufzeit beginnt bei 250 € netto. Die Software lässt sich kostenlos testen.</p><h3>Fazit</h3><p>Für kleine Betriebe mit etwas technischem Verständnis ist ecoDMS eine hervorragende Lösung zum kleinen Preis. Wer Workflows und Cloud braucht, sollte DocuWare oder d.velop prüfen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('ELO', 'elo', 'Enterprise Content Management aus Stuttgart', 'ECM-Lösung für Archivierung, Workflows und digitale Akten, vom Mittelstand bis zum Konzern.', '<p>ELO Digital Office bietet ECM-Lösungen für revisionssichere Archivierung, digitale Akten und Workflows. Die Produkte decken vom Mittelstand (ELO professional) bis zum Konzern (ELO enterprise) unterschiedliche Größen ab.</p><p>Betrieben wird ELO meist im eigenen Rechenzentrum oder beim Partner.</p>', null, (select id from public.categories where slug = 'dokumentenmanagement'), null, 'EUR', 'month', true, 'user', false, null, false, true, '[]'::jsonb, null, '["Revisionssichere Archivierung","Volltextsuche & OCR","Rechnungseingangsworkflow","E-Rechnung (XRechnung/ZUGFeRD)","Versionierung","Rollen & Rechte","DATEV-Anbindung","E-Mail-Archivierung","Mobile App","Verfahrensdokumentation"]'::jsonb, '["Skaliert bis zum Konzern","Digitale Akten","Großes Partnernetz"]'::jsonb, '["SAP","Microsoft 365","DATEV","Outlook"]'::jsonb, '["Sehr leistungsfähig","Etablierter deutscher Anbieter"]'::jsonb, '["Einführungsprojekt nötig","Preis nur auf Anfrage"]'::jsonb, 'Mittelständler und Konzerne mit komplexen Dokumentprozessen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.elo.com/de-de.html', 'keins', 'ELO Digital Office GmbH', null, 'Stuttgart', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.2, 3.8, 3.8, 4.2, 4.8, 'ELO aus Stuttgart ist eine umfassende ECM-Plattform für Archivierung, Workflows und digitale Akten, vom Mittelstand bis zum Konzern.', '<h3>Einordnung</h3><p>ELO deckt weit mehr ab als ein Archiv. Digitale Personal-, Vertrags- und Kundenakten, Rechnungseingang und individuelle Workflows lassen sich abbilden, die Lösung skaliert bis in Konzerngröße.</p><h3>Kosten</h3><p>Preise gibt es über ELO-Partner auf Anfrage. Eine Demo ist kostenlos.</p><h3>Fazit</h3><p>Für Unternehmen mit vielen Abteilungen und hohen Anforderungen an Prozesse und Rechte ist ELO eine der stärksten Plattformen aus Deutschland.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('WISO MeinBüro', 'wiso-meinbuero', 'Rechnungen, Buchhaltung und Auftragswesen vom Hersteller von WISO Steuer', 'Bürosoftware für Selbstständige und kleine Betriebe mit Rechnungen, EÜR, Umsatzsteuer-Voranmeldung und optionaler Warenwirtschaft. 14 Tage kostenlos testbar.', '<p>WISO MeinBüro kommt aus demselben Haus wie WISO Steuer, und das merkt man an der Stelle, an der es für kleine Betriebe am meisten zählt: bei der Umsatzsteuer. Die Voranmeldung wird aus den Buchungen erzeugt und direkt übermittelt, die Einnahmenüberschussrechnung entsteht nebenbei.</p><p>Das Tarifmodell ist nach Umsatz gestaffelt. Der Einstieg für Rechnungen und Angebote gilt bis 25.000 € Jahresumsatz, der Buchhaltungstarif bis 120.000 €. Wer darüber liegt oder mehrere Nutzer braucht, wechselt in Auftragswesen oder Warenwirtschaft. Alle Tarife lassen sich 14 Tage kostenlos und ohne Zahlungsdaten testen.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 10.9, 'EUR', 'month', true, 'account', true, 14, false, false, '[{"name":"Rechnungen & Angebote","price":10.9,"period":"month","unit":"account","features":["1 Nutzer","bis 25.000 € Jahresumsatz"]},{"name":"Buchhaltung","price":19.9,"period":"month","unit":"account","features":["1 Nutzer","bis 120.000 € Jahresumsatz","EÜR und UStVA"],"highlighted":true},{"name":"Auftragswesen","price":39.9,"period":"month","unit":"account","features":["2 Nutzer","Umsatz unbegrenzt"]},{"name":"Warenwirtschaft","price":69.9,"period":"month","unit":"account","features":["5 Nutzer","Lager und Bestellwesen"]}]'::jsonb, null, '["Angebote und Rechnungen","E-Rechnung","Belegerfassung","Bankanbindung","EÜR","UStVA per ELSTER","DATEV-Export","Mahnwesen","Warenwirtschaft (Tarif Warenwirtschaft)"]'::jsonb, '["UStVA direkt aus der Buchhaltung","Tarife nach Jahresumsatz gestaffelt","Warenwirtschaft im großen Tarif"]'::jsonb, '["DATEV","ELSTER"]'::jsonb, '["Sehr gute Umsatzsteuer-Funktionen","Klare Preisstaffel nach Umsatz","Testphase ohne Zahlungsdaten"]'::jsonb, '["Umsatzgrenzen in den kleinen Tarifen","Bilanzierende Unternehmen sind nicht die Zielgruppe"]'::jsonb, 'Selbstständige und kleine Betriebe mit EÜR, die ihre Umsatzsteuer selbst erledigen.', null, 'ja', 'export', '[]'::jsonb, true, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.meinbuero.de/', 'keins', 'Buhl Data Service GmbH', null, 'Neunkirchen (Siegerland)', '["Telefon","E-Mail","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.1, 4.2, 4.2, 4, 4, 'WISO MeinBüro ist eine bodenständige Bürosoftware mit besonders guten Umsatzsteuer-Funktionen. Die Umsatzgrenzen in den kleinen Tarifen sollten Sie vor dem Kauf genau prüfen.', '<h3>Herkunft und Anspruch</h3><p>Buhl Data aus dem Siegerland kennt die meisten als Hersteller von WISO Steuer. MeinBüro überträgt dieses Steuerwissen auf den Alltag kleiner Betriebe: Rechnungen schreiben, Belege erfassen, Umsatzsteuer melden, EÜR erstellen.</p><h3>Tarife und Umsatzgrenzen</h3><p>Rechnungen und Angebote kostet 10,90 € im Monat und gilt bis 25.000 € Jahresumsatz. Buchhaltung für 19,90 € deckt bis 120.000 € ab. Darüber liegen Auftragswesen für 39,90 € mit zwei Nutzern und Warenwirtschaft für 69,90 € mit fünf Nutzern, beide ohne Umsatzgrenze. Neukunden erhalten zeitweise hohe Rabatte auf die ersten Monate.</p><p>Wer knapp unter einer Grenze liegt und wächst, sollte gleich eine Stufe höher einsteigen, um einen Wechsel mitten im Jahr zu vermeiden.</p><h3>Im Alltag</h3><p>Die Umsatzsteuer-Voranmeldung entsteht direkt aus den Buchungen und wird elektronisch übermittelt. Für die Kanzlei gibt es den DATEV-Export. Die Oberfläche ist sachlich und gut strukturiert, wenn auch weniger verspielt als bei Lexware Office.</p><h3>Test</h3><p>Alle Tarife lassen sich 14 Tage kostenlos und ohne Angabe von Zahlungsdaten testen. Das reicht, um eine Voranmeldung probeweise vorzubereiten und zu sehen, ob die Arbeitsweise passt.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('orgaMAX', 'orgamax', 'Bürosoftware vom Angebot bis zur Buchhaltung, als Cloud oder Desktop', 'Kaufmännische Komplettlösung für kleine Unternehmen mit Aufträgen, Rechnungen inklusive E-Rechnung, Projekten und optionaler Warenwirtschaft. Cloud ab 49 € im Monat.', '<p>orgaMAX aus Detmold gehört zu den Programmen, die viele Handwerks- und Dienstleistungsbetriebe seit Jahren nutzen, oft noch in der Desktopversion. Inzwischen gibt es die Software auch als Cloud, und beide Varianten folgen demselben Aufbau: Angebot, Auftrag, Lieferschein und Rechnung greifen ineinander, die Buchhaltung läuft mit.</p><p>Die Tarife unterscheiden sich weniger im Kern als in der Branchenausrichtung. Dienstleister bekommen Projektmanagement, Zeiterfassung und Abschlagsrechnungen, Händler die Lagerverwaltung mit Bestellvorschlägen, produzierende Betriebe mehrstufige Stücklisten. Eine kostenlose Testphase wird angeboten.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 49, 'EUR', 'month', true, 'account', true, null, false, false, '[{"name":"Start","price":49,"period":"month","unit":"account","features":["Angebot, Auftrag, Rechnung inkl. E-Rechnung","Lieferscheine"]},{"name":"Dienstleister","price":69,"period":"month","unit":"account","features":["Projektmanagement und Projektzeiten","CRM mit Lead-Status","Teil-, Abschlags- und Schlussrechnungen"],"highlighted":true},{"name":"Handel","price":99,"period":"month","unit":"account","features":["Warenwirtschaft und Lager","Automatische Bestellvorschläge"]},{"name":"Produktion","price":119,"period":"month","unit":"account","features":["Mehrstufige Stücklisten","Kalkulation aus Herstellkosten"]}]'::jsonb, 'Cloud, bei jährlicher Zahlung', '["Angebote und Aufträge","Rechnungen inkl. E-Rechnung","Lieferscheine","Projektmanagement","Projektzeiterfassung","CRM","Warenwirtschaft","Stücklisten","Buchhaltung","DATEV-Export"]'::jsonb, '["Branchentarife für Dienstleister, Handel und Produktion","Cloud und Desktop mit gleichem Aufbau","Abschlags- und Schlussrechnungen"]'::jsonb, '["DATEV","ELSTER"]'::jsonb, '["Deckt den ganzen Auftragsprozess ab","Auch als Desktopversion erhältlich","Branchenpakete statt Einheitsgröße"]'::jsonb, '["Oberfläche wirkt im Vergleich zu reinen Cloud-Tools traditionell","Preise im Cloud-Tarif höher als bei reinen Rechnungsprogrammen"]'::jsonb, 'Handwerks-, Handels- und Dienstleistungsbetriebe mit Auftragsabwicklung und Lager.', null, 'ja', 'export', '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.orgamax.de/', 'keins', 'deltra Business Software GmbH & Co. KG', null, 'Detmold', '["Telefon","E-Mail","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4, 3.8, 3.9, 4.1, 4.3, 'orgaMAX deckt den gesamten Weg vom Angebot bis zur Buchung ab und bietet Branchenpakete für Dienstleister, Handel und Produktion. Wer vor allem Rechnungen schreibt, zahlt hier mehr als nötig.', '<h3>Einordnung</h3><p>orgaMAX aus Detmold ist ein kleines ERP-System für Betriebe, die mehr brauchen als ein Rechnungsprogramm. Angebote werden zu Aufträgen, Lieferscheinen und Rechnungen, Zahlungen laufen in die Buchhaltung. Die Software gibt es als Cloud und als Desktopversion.</p><h3>Branchenpakete</h3><p>Das Paket Dienstleister bringt Projektmanagement, Projektzeiterfassung, ein kleines CRM und Abschlags- sowie Schlussrechnungen. Handel ergänzt Lagerverwaltung und automatische Bestellvorschläge. Produktion kommt mit mehrstufigen Stücklisten und einer Kalkulation aus den Herstellkosten.</p><h3>Preise</h3><p>In der Cloud kostet Start 49 € im Monat, Dienstleister 69 €, Handel 99 € und Produktion 119 €, jeweils bei jährlicher Zahlung. Die Desktopversionen liegen etwas darüber. Eine kostenlose Testphase wird angeboten.</p><h3>Unser Fazit</h3><p>Für Handwerks- und Handelsbetriebe mit echter Auftragsabwicklung ist orgaMAX eine gute, bodenständige Wahl. Wer nur Rechnungen schreibt, findet bei Lexware Office oder sevdesk günstigere Lösungen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Billomat', 'billomat', 'Rechnungsprogramm mit Buchhaltung und DATEVconnect', 'Online-Rechnungsprogramm mit Angeboten, Mahnungen, Bankanbindung und direkter DATEV-Verbindung ab dem Tarif Business. 14 Tage kostenlos testbar.', '<p>Billomat ist über die Jahre vom reinen Rechnungsprogramm zu einer schlanken Buchhaltung gewachsen und gehört heute zur Berliner aifinyo AG. Der Schwerpunkt liegt weiterhin auf dem Ausgangsprozess: Angebot, Rechnung, Zahlungseingang, Mahnung.</p><p>Beim Tarif lohnt ein genauer Blick. Professional ist auf 30 Dokumente im Monat begrenzt und hat weder Bankanbindung noch DATEVconnect. Erst Business öffnet unbegrenzte Dokumente, die Kontoanbindung und den Zugang für die Steuerkanzlei. Für die meisten Betriebe ist Business deshalb der eigentliche Einstieg.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 19, 'EUR', 'month', true, 'account', true, 14, false, false, '[{"name":"Professional","price":19,"period":"month","unit":"account","features":["1 Nutzer","30 Dokumente im Monat","Ohne Bankanbindung und DATEVconnect"]},{"name":"Business","price":29,"period":"month","unit":"account","features":["Unbegrenzte Dokumente","Bankanbindung","DATEVconnect und Steuerberater-Zugang"],"highlighted":true},{"name":"Enterprise","price":99,"period":"month","unit":"account","features":["5 Nutzer inklusive","Sandbox und erweiterte API","Persönlicher Ansprechpartner"]}]'::jsonb, 'bei jährlicher Zahlung; monatlich ab 29 €', '["Angebote und Rechnungen","Mahnwesen","Bankanbindung","DATEVconnect","Steuerberater-Zugang","Wiederkehrende Rechnungen","API"]'::jsonb, '["DATEVconnect ab Tarif Business","Sauberer Rechnungsprozess mit Mahnwesen","Steuerberater-Zugang"]'::jsonb, '["DATEV"]'::jsonb, '["Direkte DATEV-Verbindung","Übersichtlicher Rechnungsprozess","14 Tage kostenlos testbar"]'::jsonb, '["Kleinster Tarif stark eingeschränkt","Weitere Nutzer kosten 10 € im Monat extra"]'::jsonb, 'Freiberufler und kleine Firmen, deren Steuerkanzlei mit DATEV arbeitet.', null, null, 'vollintegriert', '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.billomat.com/', 'keins', 'aifinyo AG', null, 'Berlin', '["E-Mail","Hilfe-Center","Telefon (Enterprise)"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 3.9, 4.1, 3.7, 3.8, 3.9, 'Billomat ist ein solides Rechnungsprogramm mit direkter DATEV-Verbindung. Der kleinste Tarif ist allerdings so stark eingeschränkt, dass Business für die meisten Betriebe der eigentliche Einstieg ist.', '<h3>Worum es geht</h3><p>Billomat gehört zur Berliner aifinyo AG und konzentriert sich auf den Ausgangsprozess: Angebot, Rechnung, Zahlungseingang und Mahnung. Buchhaltungsfunktionen sind vorhanden, stehen aber nicht im Mittelpunkt.</p><h3>Tarife genau betrachtet</h3><p>Professional kostet 19 € bei jährlicher Zahlung, erlaubt aber nur 30 Dokumente im Monat, einen Nutzer und weder Bankanbindung noch DATEVconnect. Business für 29 € jährlich bringt unbegrenzte Dokumente, die Bankanbindung, DATEVconnect und den Zugang für die Steuerberatung. Enterprise für 99 € enthält fünf Nutzer und einen persönlichen Ansprechpartner.</p><p>Bei monatlicher Zahlung kosten die Tarife 29 €, 39 € und 119 €. Jeder weitere Nutzer schlägt mit 10 € im Monat zu Buche.</p><h3>Fazit</h3><p>Billomat lohnt sich für Betriebe, deren Kanzlei mit DATEV arbeitet und die vor allem einen sauberen Rechnungsprozess brauchen. Die 14 Tage kostenlose Testphase gilt für alle Tarife.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Collmex', 'collmex', 'Günstige Online-Buchhaltung mit kostenloser Einstiegsversion', 'Online-Buchhaltung und Rechnungsprogramm aus Saarbrücken mit kostenloser Version, Komplettpaketen ab 16,95 € und 30 Tagen kostenloser Testphase.', '<p>Collmex ist eines der dienstältesten Online-Buchhaltungsprogramme in Deutschland und richtet sich an Anwender, die doppelte Buchführung verstehen und kein Hochglanz-Interface brauchen. Wer Konten, Buchungssätze und Umsatzsteuer beherrscht, kommt schnell voran.</p><p>Preislich ist Collmex kaum zu schlagen: Buchhaltung und Rechnung gibt es jeweils als kostenlose Version, das Komplettpaket basic kostet 16,95 € im Monat. Dafür verzichtet man auf manchen Komfort, den jüngere Anbieter bieten, etwa bei der automatischen Belegerkennung.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 0, 'EUR', 'month', true, 'account', true, 30, true, false, '[{"name":"Buchhaltung free","price":0,"period":"month","unit":"account","features":["Kostenlose Einstiegsversion"]},{"name":"Buchhaltung basic","price":11.95,"period":"month","unit":"account","features":["Finanzbuchhaltung mit UStVA"]},{"name":"Collmex basic","price":16.95,"period":"month","unit":"account","features":["Komplettpaket Buchhaltung und Rechnung"],"highlighted":true},{"name":"Collmex pro","price":46.95,"period":"month","unit":"account","features":["Komplettpaket mit erweitertem Umfang"]}]'::jsonb, null, '["Finanzbuchhaltung","Rechnungen","UStVA","DATEV-Export","Offene Posten","Vereinsbuchhaltung (Collmex verein)"]'::jsonb, '["Kostenlose Version für Buchhaltung und Rechnung","Komplettpaket ab 16,95 €","Eigenes Paket für Vereine"]'::jsonb, '["DATEV","ELSTER"]'::jsonb, '["Sehr niedrige Kosten","Kostenlose Einstiegsversion","Solide doppelte Buchführung"]'::jsonb, '["Oberfläche nüchtern und wenig geführt","Weniger Automatisierung bei Belegen als bei jüngeren Anbietern"]'::jsonb, 'Buchhaltungskundige Kleinunternehmer und Vereine mit knappem Budget.', null, null, 'export', '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.collmex.de/', 'keins', 'Collmex GmbH', null, 'Saarbrücken', '["E-Mail","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 3.9, 3.4, 4.7, 3.7, 4, 'Collmex ist die günstigste ernstzunehmende Buchhaltung für Anwender, die doppelte Buchführung beherrschen. Wer eine geführte, moderne Oberfläche erwartet, wird enttäuscht.', '<h3>Für wen Collmex gedacht ist</h3><p>Collmex aus Saarbrücken ist seit vielen Jahren am Markt und richtet sich an Menschen, die Buchungssätze, Konten und Umsatzsteuer verstehen. Die Software nimmt einem wenig ab, lässt einen dafür aber auch zügig arbeiten.</p><h3>Preise</h3><p>Buchhaltung und Rechnung gibt es jeweils in einer kostenlosen Version. Buchhaltung light kostet 8,95 €, Buchhaltung basic 11,95 €. Die Komplettpakete aus Buchhaltung und Rechnung kosten 16,95 €, 24,95 € oder 46,95 € im Monat. Für Vereine gibt es ein eigenes Paket für 13,95 €. Die ersten 30 Tage sind eine kostenlose Testphase.</p><h3>Stärken und Schwächen</h3><p>Das Preis-Leistungs-Verhältnis ist hervorragend, die Buchhaltung selbst solide mit Umsatzsteuer-Voranmeldung und DATEV-Export. Bei Belegerkennung, Bankabgleich und Bedienkomfort liegen jüngere Anbieter aber deutlich vorn.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('JTL-Wawi', 'jtl-wawi', 'Kostenlose Warenwirtschaft für den Onlinehandel', 'Warenwirtschaft für E-Commerce mit Marktplatzanbindung und eigenem Shop, in der Edition JTL Start dauerhaft kostenlos.', '<p>JTL-Wawi ist im deutschen Onlinehandel ein Begriff. Die Software verwaltet Artikel, Bestände, Aufträge und Versand und bindet Shops und Marktplätze an. Die Edition JTL Start ist als lokale Installation dauerhaft kostenlos und erlaubt unbegrenzt viele Nutzer.</p><p>Kosten entstehen, wenn der Handel wächst: Ein professioneller Shop mit unbegrenzten Artikeln gehört zu JTL Advanced, mehrere Shops und Automatisierung zu JTL Pro. Weil die Software lokal läuft, braucht man einen eigenen Rechner oder Server und etwas Einarbeitung. Ein großes Partnernetz hilft bei der Einrichtung.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 0, 'EUR', 'month', true, 'account', false, null, true, true, '[{"name":"JTL Start","price":0,"period":"month","unit":"account","features":["Dauerhaft kostenlos","Unbegrenzte Nutzer","Shop bis 500 Artikel"]},{"name":"JTL Advanced","price":119,"period":"month","unit":"account","features":["1 professioneller Shop","Unbegrenzte Artikel"],"highlighted":true},{"name":"JTL Pro","price":369,"period":"month","unit":"account","features":["3 Shops","Workflow-Automatisierung"]}]'::jsonb, null, '["Artikelverwaltung","Lager und Bestände","Auftragsabwicklung","Versand","Marktplatzanbindung","Onlineshop","DATEV-Export","Workflows"]'::jsonb, '["Dauerhaft kostenlose Edition","Unbegrenzte Nutzer schon im Start-Tarif","Großes Partnernetz im Onlinehandel"]'::jsonb, '["JTL-Shop","Amazon","eBay","Shopify","DATEV"]'::jsonb, '["Kostenloser Einstieg ohne Nutzerlimit","Stark im Multichannel-Handel","Viele Erweiterungen"]'::jsonb, '["Lokale Installation mit eigenem Pflegeaufwand","Einarbeitung braucht Zeit"]'::jsonb, 'Onlinehändler, die mehrere Kanäle aus einer Warenwirtschaft steuern wollen.', null, null, 'export', '[]'::jsonb, null, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.jtl-software.com/de', 'keins', 'JTL-Software-GmbH', null, 'Hückelhoven', '["Hilfe-Center","Community","Servicepartner"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 3.8, 4.8, 3.9, 4.5, 'JTL-Wawi ist für Onlinehändler die naheliegende erste Warenwirtschaft: dauerhaft kostenlos, mit unbegrenzt vielen Nutzern und einer großen Community. Wachstum kostet dann Geld und Pflegeaufwand.', '<h3>Warum so viele Händler damit starten</h3><p>JTL aus Hückelhoven bietet die Warenwirtschaft als lokale Installation in der Edition JTL Start dauerhaft kostenlos an, mit unbegrenzten Nutzern und einem kostenlosen Shop mit bis zu 500 Artikeln. Für Händler, die auf Amazon, eBay und im eigenen Shop verkaufen, ist das ein sehr günstiger Einstieg.</p><h3>Kosten beim Wachstum</h3><p>JTL Advanced mit einem professionellen Shop und unbegrenzten Artikeln kostet 119 € im Monat, bei jährlicher Zahlung weniger. JTL Pro mit drei Shops und Workflow-Automatisierung liegt bei 369 €. Lagerverwaltung und Versand haben eigene Preisstufen.</p><h3>Worauf Sie achten sollten</h3><p>Weil die Software lokal läuft, brauchen Sie einen Rechner oder Server und kümmern sich um Updates und Sicherungen. Viele Händler holen sich dafür einen JTL-Servicepartner.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage 50 Handwerk', 'sage-50-handwerk', 'Die kaufmännische Komplettlösung für Handwerksbetriebe', 'Auftragsbearbeitung, Projektverwaltung und Rechnungen für das Handwerk mit E-Rechnung, Großhändlerschnittstellen und mobilem Arbeiten. Ab 19,90 € im Monat.', '<p>Sage 50 Handwerk ist auf die Abläufe eines Handwerksbetriebs zugeschnitten: Angebot mit Aufmaß, Auftrag, Teil- und Schlussrechnung. Die Software spricht die Sprache der Branche, von GAEB-Ausschreibungen bis zu den Großhändlerschnittstellen IDS und OCI, über die sich Preise und Verfügbarkeiten direkt abrufen lassen.</p><p>Der Einstieg Essential kostet 19,90 € im Monat für einen Benutzer, die Version Enterprise mit unbegrenzten Benutzern, Terminkalender und Teilrechnungen 59 €. Beide Preise gelten bei jährlicher Zahlung. Mit einem Cloud-Paket lässt sich die Software auch auf der Baustelle nutzen. Sage bietet Webinare und ein kostenloses Infopaket, eine Selbsttestversion gibt es nicht.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 19.9, 'EUR', 'month', true, 'account', false, null, false, true, '[{"name":"Essential","price":19.9,"period":"month","unit":"account","features":["1 Benutzer","Angebote, Aufträge, Rechnungen","E-Rechnung (ZUGFeRD 2.1, XRechnung)","Projektverwaltung"]},{"name":"Enterprise","price":59,"period":"month","unit":"account","features":["Unbegrenzte Benutzer","Teil- und Schlussrechnungen","Terminkalender","Optional: Nachkalkulation, Wartung und Service, Fibu"],"highlighted":true}]'::jsonb, 'bei jährlicher Zahlung, 12 Monate Laufzeit', '["Angebote, Aufträge, Rechnungen","E-Rechnung (ZUGFeRD 2.1, XRechnung)","Projektverwaltung","Teil- und Schlussrechnungen","Aufmaß","GAEB","IDS und OCI","Termin- und Ressourcenplanung","Mobile Zeiterfassung","DMS"]'::jsonb, '["Großhändlerschnittstellen IDS und OCI","GAEB für Ausschreibungen","Mobil auf der Baustelle mit Cloud-Paket"]'::jsonb, '["Großhandel (IDS/OCI)","GAEB"]'::jsonb, '["Konsequent auf das Handwerk ausgerichtet","Günstiger Einstieg für Einzelbetriebe","Branchenschnittstellen ab Werk"]'::jsonb, '["Keine kostenlose Selbsttestversion","Viele Zusatzmodule kosten extra"]'::jsonb, 'Handwerksbetriebe vom Einmannbetrieb bis zur mittleren Firma mit Baustellenbetrieb.', null, null, null, '["XRechnung","ZUGFeRD"]'::jsonb, null, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-50-handwerk/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["Telefon","E-Mail","Webinare"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.2, 4.1, 4.2, 4.1, 4.3, 'Sage 50 Handwerk ist konsequent auf die Abläufe im Handwerk zugeschnitten, mit Aufmaß, Teilrechnungen und Großhändlerschnittstellen. Der Einstieg für 19,90 € im Monat ist für Einzelbetriebe sehr fair.', '<h3>Warum eine Branchenlösung</h3><p>Ein Elektro- oder Sanitärbetrieb rechnet anders als ein Onlinehändler. Angebote entstehen aus Aufmaß und Leistungsverzeichnis, Rechnungen kommen in Abschlägen, und Materialpreise ändern sich ständig. Sage 50 Handwerk bildet genau das ab.</p><h3>Stärken</h3><p>Über die Schnittstellen IDS und OCI rufen Sie Preise und Verfügbarkeiten direkt beim Großhandel ab, ohne abzutippen. Ausschreibungen im GAEB-Format lassen sich einlesen. E-Rechnungen im Format ZUGFeRD 2.1 und XRechnung erstellt die Software direkt, was besonders bei öffentlichen Auftraggebern wichtig ist.</p><p>Mit einem Cloud-Paket lassen sich Leistungen und Arbeitszeiten auf der Baustelle erfassen. Zusatzpakete für mobiles Arbeiten, Zeiterfassung und Dokumentenmanagement sind verfügbar.</p><h3>Preise</h3><p>Essential für einen Benutzer kostet 19,90 € im Monat, Enterprise mit unbegrenzten Benutzern, Teil- und Schlussrechnungen und Terminkalender 59 €, jeweils bei jährlicher Zahlung mit zwölf Monaten Laufzeit. Nachkalkulation, Wartung und Service sowie die Finanzbuchhaltung sind optional erweiterbar. Eine Selbsttestversion gibt es nicht, dafür Webinare und ein kostenloses Infopaket.</p><h3>Fazit</h3><p>Für Handwerksbetriebe vom Einmannbetrieb bis zur mittleren Firma ist Sage 50 Handwerk eine der rundesten Branchenlösungen am Markt.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true)
